<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login();
$uid=(int)current_user()['id'];
if(is_post()){verify_csrf();$action=$_POST['action']??'';if($action==='read'){$id=(int)($_POST['id']??0);$st=$db->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE id=? AND user_id=?');$st->execute([$id,$uid]);}elseif($action==='read_all'){$st=$db->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE user_id=? AND is_read=0');$st->execute([$uid]);}redirect('notifications.php');}
$rows=[];if($db){$st=$db->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY is_read ASC,created_at DESC LIMIT 100');$st->execute([$uid]);$rows=$st->fetchAll();}
?><!doctype html><html lang="<?=e($LANG)?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications — WDH</title><link rel="stylesheet" href="assets/css/style.css?v=wdh-ui-v8"><link rel="stylesheet" href="assets/css/catalog.css?v=wdh-ui-v8"></head><body><?php require __DIR__.'/includes/header.php';?><main class="portal-page"><div class="breadcrumbs">Home › Client Portal › Notifications</div><div class="portal-welcome"><div><span class="eyebrow mint">CLIENT PORTAL</span><h1>Notifications</h1><p>Service activation, credential updates, renewals and account alerts.</p></div><div class="actions"><form method="post"><?=csrf_field()?><button class="btn secondary" name="action" value="read_all">Mark all as read</button></form><a class="btn secondary" href="client.php">Dashboard</a></div></div><div class="notification-list"><?php if(!$rows):?><div class="cart-card"><h3>No notifications</h3><p class="muted">You’re all caught up.</p></div><?php else:foreach($rows as $n):?><article class="notification-item <?=$n['is_read']?'read':'unread'?>"><div><span class="eyebrow mint"><?=e(strtoupper(str_replace('_',' ',$n['type'])))?></span><h3><?=e($n['title'])?></h3><p><?=nl2br(e($n['message']))?></p><small><?=e($n['created_at'])?></small></div><div class="actions"><?php if($n['link_url']):?><a class="btn primary small" href="<?=e($n['link_url'])?>">View</a><?php endif;?><?php if(!$n['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn secondary small" name="action" value="read">Mark read</button></form><?php endif;?></div></article><?php endforeach;endif;?></div></main><?php require __DIR__.'/includes/footer.php';?></body></html>
